Script.Source:
import sailpoint.object.Form;

Object objType = field.getValue();

Form.Section section = null ;

switch(objType) {

  case "User" : section = form.getSection("Service Principal");
    form.remove(section);
    section = form.getSection("User");
    break;
  case "Service Principal" : section = form.getSection("User");
    form.remove(section);
    section = form.getSection("Service Principal");
    break;
}
if (section != null && section.getFields() != null ) {
    section.getFields().get(0).setRequired(true);
}
return false;
